import{_ as r,o as d,c as e,a5 as a}from"./chunks/framework.R-FQ1xZ2.js";const m=JSON.parse('{"title":"L6 · 评测与可观测","description":"","frontmatter":{"title":"L6 · 评测与可观测","layer":"L6","layerTitle":"L6 · 评测与可观测","order":0,"points":[],"freq":"高","hours":28,"tags":["评测","可观测","ground-truth","LLM-as-judge","回归门禁","面试高频"]},"headers":[],"relativePath":"kb/l6-eval-observability/index.md","filePath":"kb/l6-eval-observability/index.md","lastUpdated":null}'),o={name:"kb/l6-eval-observability/index.md"};function s(n,t,l,g,h,i){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="l6-·-评测与可观测" tabindex="-1">L6 · 评测与可观测 <a class="header-anchor" href="#l6-·-评测与可观测" aria-label="Permalink to &quot;L6 · 评测与可观测&quot;">​</a></h1><blockquote><p>本层知识点导览 ｜ <strong>14 个知识点 / 6 页 / 28 学时</strong> ｜ 面试频率：高 9 项、中 5 项</p></blockquote><h2 id="这一层在解决什么问题" tabindex="-1">这一层在解决什么问题 <a class="header-anchor" href="#这一层在解决什么问题" aria-label="Permalink to &quot;这一层在解决什么问题&quot;">​</a></h2><p>L1 讲模型怎么算，L2 讲怎么把话说清楚，L3 讲怎么把材料找对，L4 讲怎么让 Agent 动起来，L5 讲怎么把它跑在生产上。<strong>L6 回答的是唯一一个贯穿前面五层的问题：你怎么知道它变好了？</strong></p><p>这不是一个「加个分数」的问题，而是一个<strong>测量学问题</strong>。LLM 应用是概率系统：同一个 prompt 跑两遍能得到两个答案，所以「变好」在这类系统里<strong>没有默认含义</strong>——它必须先被定义成一组 <code>(题集版本, gt 版本, 指标口径, 比较对象)</code> 四元组齐全、可复算的数字。<strong>没有这四元组，所有关于效果的讨论都是手感。</strong></p><p>这一层的独特之处在于：<strong>它是对前面五层的元层，也是最容易被跳过的一层</strong>。</p><ul><li>它与<strong>上游</strong>的关系：L3 的检索指标、L5 的可观测三支柱，本质都是本层的实例。本层不去重讲它们怎么实现，而是讲<strong>它们的数字在什么条件下才可信</strong>。</li><li>它与<strong>下游</strong>的关系：没有评测，L7 的微调决策只能靠感觉；没有回归门禁，L5 的每一次迭代都在赌。</li></ul><p>三句话概括这层的核心判断：</p><ol><li><strong>尺子先于系统。</strong> 先定义怎么量，再动手改；反过来做，改动的方向由手感决定。</li><li><strong>分母决定含义。</strong> 同一个数字，换分母就是另一件事。<strong>报数必带口径</strong>是这一层唯一的硬纪律。</li><li><strong>被测系统不能参与出题。</strong> 拿检索结果当 gt、拿模型当裁判又不校准，指标就变成自证。</li></ol><h2 id="页面结构与学习顺序" tabindex="-1">页面结构与学习顺序 <a class="header-anchor" href="#页面结构与学习顺序" aria-label="Permalink to &quot;页面结构与学习顺序&quot;">​</a></h2><blockquote><p><code>01</code>–<code>03</code> 三页覆盖 L6-01 → L6-06；<strong><code>04</code>–<code>06</code> 三页由另一批撰写</strong>，本表按同一份页面划分表（<code>_specs/kb-pageplan.md</code> §6）预留位置。</p></blockquote><table tabindex="0"><thead><tr><th>order</th><th>页面</th><th>覆盖知识点</th><th>频率</th><th>学时</th><th>依赖（先学什么）</th></tr></thead><tbody><tr><td>1</td><td><a href="./01-why-evaluate.html">① 为什么必须评测、评测集与合成数据</a></td><td>L6-01 / 02 / 03</td><td>高</td><td>6</td><td>—（本层入口）</td></tr><tr><td>2</td><td><a href="./02-retrieval-metrics.html">② 检索端指标（Recall@k / MRR / nDCG / Hit Rate）</a></td><td>L6-04</td><td>高</td><td>2</td><td>先有 ① 的「gt 从哪来」</td></tr><tr><td>3</td><td><a href="./03-generation-metrics.html">③ 生成端指标与通用 NLP 指标</a></td><td>L6-05 / 06</td><td>高</td><td>4</td><td>依赖 ② 的「归因」概念</td></tr><tr><td>4</td><td>④ LLM-as-a-Judge（撰写中）</td><td>L6-07 / 08</td><td>高</td><td>4</td><td>依赖 ③ 的指标定义</td></tr><tr><td>5</td><td>⑤ 多轮与 Agent 轨迹评测（撰写中）</td><td>L6-09 / 10</td><td>高</td><td>4</td><td>依赖 ③ 与 L4 的 Agent 循环</td></tr><tr><td>6</td><td>⑥ 评测框架、CI 回归门禁与线上监控（撰写中）</td><td>L6-11 / 12 / 13 / 14</td><td>高</td><td>8</td><td><strong>最后一页</strong>：把前面所有指标接进流水线</td></tr></tbody></table><p><strong>本层合计</strong>：<strong>14 个知识点，约 28 小时</strong>（其中 <code>01</code>–<code>03</code> 共 12 小时已可读）。</p><p><strong>读法建议</strong>：</p><ul><li><strong>第一遍（约 3 天，每天 2–3h）</strong>：按 ① → ② → ③ 顺序读。①是地基（评测集与 gt 纪律），②③ 是两套尺子。<strong>每页都要回到自己的两个项目上对一遍</strong>——你的报告里踩过的坑，这三页全都有对应条目。</li><li><strong>第二遍（约 3 天）</strong>：读 ④ → ⑤ → ⑥。这三页是<strong>把单点指标变成流程</strong>：裁判怎么信（④）、过程和结果怎么分工（⑤）、怎么接进 CI 与线上（⑥）。</li><li><strong>面试前一天</strong>：只看每页的「面试怎么问」与「自检清单」，以及下面的<strong>最容易挂在哪</strong>。</li><li><strong>不能跳的顺序</strong>：① → ② → ③ 不能跳（评测集 → 检索尺子 → 生成尺子是同一条逻辑链）。④ 与 ⑤ 可以交换顺序，但 ⑥ 必须在这两者之后——<strong>门禁是在指标定义稳定之后才成立的</strong>。</li></ul><h2 id="覆盖自检表-l6-01-→-l6-14-共-14-条-不漏不重" tabindex="-1">覆盖自检表（L6-01 → L6-14，共 14 条，不漏不重） <a class="header-anchor" href="#覆盖自检表-l6-01-→-l6-14-共-14-条-不漏不重" aria-label="Permalink to &quot;覆盖自检表（L6-01 → L6-14，共 14 条，不漏不重）&quot;">​</a></h2><blockquote><p>用法：学完一页勾一页；<strong>每个编号只归属一个页面，出现两次即为规划错误</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>编号</th><th>知识点</th><th>落在哪页</th><th>完成</th></tr></thead><tbody><tr><td>L6-01</td><td>为什么 LLM 应用必须评测</td><td><a href="./01-why-evaluate.html">① 为什么必须评测</a></td><td>☐</td></tr><tr><td>L6-02</td><td>评测集构建方法</td><td><a href="./01-why-evaluate.html">① 为什么必须评测</a></td><td>☐</td></tr><tr><td>L6-03</td><td>合成测试集生成（Testset Generation）</td><td><a href="./01-why-evaluate.html">① 为什么必须评测</a></td><td>☐</td></tr><tr><td>L6-04</td><td>RAG 检索端指标（Recall@k / MRR / nDCG / Hit Rate）</td><td><a href="./02-retrieval-metrics.html">② 检索端指标</a></td><td>☐</td></tr><tr><td>L6-05</td><td>RAG 生成端指标（faithfulness / answer relevancy / 上下文精确率）</td><td><a href="./03-generation-metrics.html">③ 生成端指标</a></td><td>☐</td></tr><tr><td>L6-06</td><td>通用指标与经典 NLP 指标（P/R/F1、BLEU、ROUGE、BERTScore 的适用与误用）</td><td><a href="./03-generation-metrics.html">③ 生成端指标</a></td><td>☐</td></tr><tr><td>L6-07</td><td>LLM-as-a-Judge</td><td>④ LLM-as-a-Judge（撰写中）</td><td>☐</td></tr><tr><td>L6-08</td><td>Judge 对齐与偏差治理</td><td>④ LLM-as-a-Judge（撰写中）</td><td>☐</td></tr><tr><td>L6-09</td><td>多轮对话与 Agent 轨迹评测</td><td>⑤ 多轮与 Agent 轨迹评测（撰写中）</td><td>☐</td></tr><tr><td>L6-10</td><td>Agent 评测基准（GAIA 等）</td><td>⑤ 多轮与 Agent 轨迹评测（撰写中）</td><td>☐</td></tr><tr><td>L6-11</td><td>评测框架使用（Ragas / DeepEval / TruLens）</td><td>⑥ 框架、CI 与监控（撰写中）</td><td>☐</td></tr><tr><td>L6-12</td><td>评测接入 CI 与回归门禁</td><td>⑥ 框架、CI 与监控（撰写中）</td><td>☐</td></tr><tr><td>L6-13</td><td>线上监控与质量告警</td><td>⑥ 框架、CI 与监控（撰写中）</td><td>☐</td></tr><tr><td>L6-14</td><td>人工评估与标注流程</td><td>⑥ 框架、CI 与监控（撰写中）</td><td>☐</td></tr></tbody></table><p><strong>自检结果</strong>：14 个编号<strong>全部出现且仅出现一次</strong>；<code>01</code>–<code>03</code> 页的 frontmatter <code>points</code> 与本表逐条对应（<code>01</code> = L6-01/02/03、<code>02</code> = L6-04、<code>03</code> = L6-05/06）；<code>order</code> 无重复（0/1/2/3/4/5/6，<code>index.md</code> 为 0）。</p><h2 id="必须能画出来的图" tabindex="-1">必须能画出来的图 <a class="header-anchor" href="#必须能画出来的图" aria-label="Permalink to &quot;必须能画出来的图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>图的内容</th><th>画在哪页</th><th>图库对应</th></tr></thead><tbody><tr><td>1</td><td><strong>评测要回答的三个层次</strong>（有没有尺子 → 尺子准不准 → 尺子量的是什么），以及跳过每一层的后果</td><td><a href="./01-why-evaluate.html">①</a></td><td><a href="/learn/diagrams/rag-eval-harness.html">/diagrams/rag-eval-harness</a></td></tr><tr><td>2</td><td><strong><code>Recall@10 == Recall@5</code> 的完整因果链</strong>（死参数 → 标注窗口 → gt ⊆ top-5 → 名次分布 21/0 → 11–14pp）</td><td><a href="./01-why-evaluate.html">①</a> ｜ <a href="./02-retrieval-metrics.html">②</a></td><td><a href="/learn/diagrams/rag-eval-harness.html">/diagrams/rag-eval-harness</a></td></tr><tr><td>3</td><td><strong>检索端指标的归因决策树</strong>（没进 top-k = 召回问题；进了但靠后 = 排序问题；进了且靠前 = 生成问题）</td><td><a href="./02-retrieval-metrics.html">②</a></td><td><a href="/learn/diagrams/rag-eval-harness.html">/diagrams/rag-eval-harness</a></td></tr><tr><td>4</td><td><strong>检索端与生成端是两套尺子</strong>（输入不同、分母不同、数字不可互推），并在同一张图里标出经典指标的失效分支</td><td><a href="./03-generation-metrics.html">③</a></td><td><a href="/learn/diagrams/rag-eval-harness.html">/diagrams/rag-eval-harness</a></td></tr><tr><td>5</td><td><strong>一个数字要进结论要过的四道口径关</strong>（有分母 → 分母够大 → 同批次同尺子 → 裁判已校准）</td><td><a href="./03-generation-metrics.html">③</a></td><td><a href="/learn/diagrams/rag-eval-harness.html">/diagrams/rag-eval-harness</a></td></tr><tr><td>6</td><td><strong>评测闭环与 CI 门禁</strong>：离线评测 → 阈值判定 → 三态退出码（通过 / 回归 / <strong>不可比</strong>）→ 阻断合并</td><td>⑥（撰写中）</td><td><a href="/learn/diagrams/rag-regression-gate.html">/diagrams/rag-regression-gate</a></td></tr><tr><td>7</td><td><strong>线上监控与质量告警</strong>：指标漂移 → bad case 采样 → 回填评测集 → 下一轮离线评测（数据飞轮）</td><td>⑥（撰写中）</td><td><a href="/learn/diagrams/yyhelp-observability.html">/diagrams/yyhelp-observability</a></td></tr></tbody></table><blockquote><p>图库里已交付的评测类图：<a href="/learn/diagrams/rag-eval-harness.html">分层评测体系</a>、<a href="/learn/diagrams/rag-regression-gate.html">回归门禁与三态退出码</a>、<a href="/learn/diagrams/yyhelp-observability.html">可观测与告警</a>、<a href="/learn/diagrams/yyhelp-ab-statistics.html">AB 配对检验与三态结论</a>。全部：<a href="/learn/diagrams/">/diagrams/</a></p></blockquote><h2 id="这一层最容易挂在哪" tabindex="-1">这一层最容易挂在哪 <a class="header-anchor" href="#这一层最容易挂在哪" aria-label="Permalink to &quot;这一层最容易挂在哪&quot;">​</a></h2><ol><li><p><strong>报一个没有分母的百分比。</strong> <code>100.0%</code> 分母只有 <strong>6 道题</strong>时几乎不含信息；<code>71.8%</code> 不带「124 题 / gt 206 块 / 密度 1.66 / 含精排」就是不可复算的。<strong>这一条是初筛与一面共同的高频死亡点</strong>——因为面试官只要追问一句样本量，答不出来整份简历的数字全部失效。</p></li><li><p><strong>把 <code>Recall@10 == Recall@5</code> 读成「排序完美」。</strong> 真相是<strong>标注窗口造成的构造结果</strong>：gt 候选只取 <code>retrieve()[:5]</code>，人也只看前 5 个，所以 <code>R@10</code> 在数学上不可能高于 <code>R@5</code>。<strong>要先排除构造性解释，再怀疑模型</strong>——这个顺序反了，排序问题会从待办清单里消失（实测名次分布 1–5 位 21 道、6–10 位 0 道）。</p></li><li><p><strong>拿被测系统的输出当 ground truth。</strong> 机器 gt 的候选<strong>由检索结果生成</strong>，再拿同一个检索器去评它就是自证——某组 <code>R@5 = 100.0%</code> 就是这么来的。正确处置不是删报告，而是<strong>让报告自己声明无效</strong>（那份报告顶部写着「🚫 不可作为结论」）。<strong>指标的可信度取决于流程是否独立于被测系统，不取决于数字多高。</strong></p></li><li><p><strong>跨报告沿列连读。</strong> <strong>16 份历史报告跨越 ≥4 把尺子</strong>（gt 版本 / gt 块数 / 题数不同），同一列上下两行的分母不是同一个东西。<strong>换尺子会让分数掉</strong>——独立盲标后 Recall 从 <strong>87.0% → 71.0%</strong>，掉下来的 16 个点是原来的虚高部分，不是系统退步。</p></li><li><p><strong>裁判没校准就当结论用。</strong> 答案准确率 <strong>65.2% / 91.3%</strong> 是<strong>旧 30 题</strong>口径、且 <strong>LLM 裁判未人工校准</strong>，与当前 <strong>130 题</strong>报告不是同一批次。<strong>严格与宽松差 26.1pp 这个分差本身就是诊断信号</strong>——它说明评分规则没定死，而不是「模型时好时坏」。</p></li><li><p><strong>只验「脚本没报错」。</strong> 配置类与流程类假设必须配<strong>能失败的断言</strong>：gt 若全部落在 top-5 内就该抛异常；被标为「不可回答」却已填 gt 块的题就该抛异常。<strong>一个恒等关系成立时，脚本是跑得好好的</strong>——只验「没报错」等于没验。</p></li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>项目：<a href="/learn/projects/rag/08-evaluation.html">⑨ 评测体系</a> —— 130 题、gt 206 块、盲标打脸的完整原文</li><li>项目：<a href="/learn/projects/rag/09-ablations.html">⑩ 消融实验</a> —— 三档检索配置与切片档位的消融口径</li><li>项目：<a href="/learn/projects/rag/10-regression.html">⑪ 回归与门禁</a> —— 确定性断言与三态退出码</li><li>项目：<a href="/learn/projects/yyhelp/11-evaluation.html">⑫ 评测与回归门禁</a> —— 40 题评测集与配对检验的实测</li><li>上层依赖：<a href="/learn/kb/l3-rag/">L3 · RAG 检索增强</a> ｜ <a href="/learn/kb/l4-agent/">L4 · Agent 与工具生态</a> ｜ <a href="/learn/kb/l5-engineering/">L5 · 工程化与服务部署</a></li><li>面试速记：<a href="/learn/interview/cheatsheet.html">/interview/cheatsheet</a></li></ul>',26)])])}const p=r(o,[["render",s]]);export{m as __pageData,p as default};
